document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("conception-date-form"),e=document.getElementById("conception-result");t.addEventListener("submit",function(t){t.preventDefault();const n=document.getElementById("birth-date").value,a=parseInt(document.getElementById("correction").value,10);if(!n)return e.textContent="Please enter the baby's birth date.",void 0;const o=new Date(n);if(isNaN(o))return e.textContent="Invalid date format.",void 0;const r=new Date(o),i=266+7*a;r.setDate(r.getDate()-i);const d=`${r.getFullYear()}-${String(r.getMonth()+1).padStart(2,"0")}-${String(r.getDate()).padStart(2,"0")}`,c=r.toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"});let s="";0!==a&&(s=` (adjusted by ${a>0?"+":""}${a} week${1===Math.abs(a)?"":"s"})`),e.innerHTML=`\n      <b>Estimated conception date:</b><br>\n      ${c}<br>\n      <small>(${d}${s})</small><br><br>\n      <em>Note: This is an estimate based on a standard 38-week gestation period from conception to birth. Actual conception timing can vary.</em>\n    `})});